<?php namespace App\Http\Controllers\Inventory;
use App\Http\Controllers\Controller; use App\Models\{Product,Warehouse}; use App\Services\InventoryService; use Illuminate\Http\Request;
class StockController extends Controller { public function adjust(Request $r,InventoryService $s){$d=$r->validate(['product_id'=>'required|integer|exists:products,id','warehouse_id'=>'required|integer|exists:warehouses,id','quantity'=>'required|numeric|between:-999999999,999999999','note'=>'nullable|string|max:500']);$p=Product::findOrFail($d['product_id']);$w=Warehouse::findOrFail($d['warehouse_id']);$s->adjust($p,$w,(float)$d['quantity'],'adjustment',null,$d['note']??null,$r);return back()->with('success','Stock adjusted.');} public function transfer(Request $r,InventoryService $s){$d=$r->validate(['product_id'=>'required|integer|exists:products,id','from_warehouse_id'=>'required|integer|exists:warehouses,id','to_warehouse_id'=>'required|integer|exists:warehouses,id|different:from_warehouse_id','quantity'=>'required|numeric|gt:0','note'=>'nullable|string|max:500']);$s->transfer(Product::findOrFail($d['product_id']),Warehouse::findOrFail($d['from_warehouse_id']),Warehouse::findOrFail($d['to_warehouse_id']),(float)$d['quantity'],$d['note']??null,$r);return back()->with('success','Stock transferred.');}}
